// ignore_for_file: unused_element, unnecessary_cast

import 'package:pulumi/pulumi.dart';
import 'allowed_client_response.dart';

/// Result data returned by getNfsShare.
class GetNfsShareResult {
  /// List of allowed access points.
  final List<AllowedClientResponse> allowedClients;

  /// Labels as key value pairs.
  final Map<String, String> labels;

  /// Immutable. The name of the NFS share.
  final String name;

  /// An identifier for the NFS share, generated by the backend. This field will be deprecated in the future, use `id` instead.
  final String nfsShareId;

  /// Immutable. Pod name. Pod is an independent part of infrastructure. NFSShare can only be connected to the assets (networks, instances) allocated in the same pod.
  final String pod;

  /// The requested size, in GiB.
  final String requestedSizeGib;

  /// The state of the NFS share.
  final String state;

  /// Immutable. The storage type of the underlying volume.
  final String storageType;

  /// The underlying volume of the share. Created automatically during provisioning.
  final String volume;

  GetNfsShareResult({
    required this.allowedClients,
    required this.labels,
    required this.name,
    required this.nfsShareId,
    required this.pod,
    required this.requestedSizeGib,
    required this.state,
    required this.storageType,
    required this.volume,
  });

  Map<String, dynamic> toMap() {
    final map = <String, dynamic>{};
    map['allowedClients'] =
        Input.encodeList<AllowedClientResponse, Map<String, dynamic>>(
            allowedClients, (value) => value.toMap());
    map['labels'] = labels;
    map['name'] = name;
    map['nfsShareId'] = nfsShareId;
    map['pod'] = pod;
    map['requestedSizeGib'] = requestedSizeGib;
    map['state'] = state;
    map['storageType'] = storageType;
    map['volume'] = volume;
    return map;
  }

  factory GetNfsShareResult.fromMap(Map<String, dynamic> map) {
    return GetNfsShareResult(
      allowedClients: Input.decodeList<AllowedClientResponse>(
          map['allowedClients'],
          (value) => AllowedClientResponse.fromMap(
              (value as Map).cast<String, dynamic>())),
      labels: (map['labels'] as Map).cast<String, String>(),
      name: map['name'] as String,
      nfsShareId: map['nfsShareId'] as String,
      pod: map['pod'] as String,
      requestedSizeGib: map['requestedSizeGib'] as String,
      state: map['state'] as String,
      storageType: map['storageType'] as String,
      volume: map['volume'] as String,
    );
  }
}
